import { createHash } from 'node:crypto';
export class BankrecError extends Error {
    code;
    constructor(code, message) { super(`${code}: ${message}`); this.name = 'BankrecError'; this.code = code; }
}
export function sha256Hex(value) { return createHash('sha256').update(value).digest('hex'); }
/** Stable 16-hex row key used to keep primary keys stable across imports. */
export function rowKey(parts) { return sha256Hex(parts.map(String).join('|')).slice(0, 16); }
/**
 * Primary key for one statement row. It carries the account, the period, a prefix of the
 * evidence hash and a stable row key, so the same file is idempotent while two different
 * files (or accounts/periods) can never silently overwrite each other.
 */
export function txnId(source, account, period, evidence, keyParts) { return `${source}-${account}-${period}-${evidence.slice(0, 12)}-${rowKey(keyParts)}`; }
export function cents(raw) { const v = raw.trim().replace(/[¥￥,\s]/g, ''); const m = /^(-?)(\d+)(?:\.(\d{1,2}))?$/.exec(v); if (!m)
    throw new BankrecError('E_BR_CSV_INVALID', `bad amount: ${raw}`); const sign = m[1] === '-' ? -1 : 1; return sign * (Number(m[2]) * 100 + Number((m[3] ?? '').padEnd(2, '0'))); }
export function parseCsv(text, side, account_id, period, evidence) {
    const lines = text.trim().split(/\r?\n/).filter(Boolean);
    if (lines.length < 2)
        throw new BankrecError('E_BR_CSV_INVALID', 'CSV needs header+rows');
    const head = lines[0].split(',').map(x => x.trim().toLowerCase());
    const di = head.indexOf('date'), ai = head.indexOf('amount'), ri = head.indexOf('reference');
    if (di < 0 || ai < 0)
        throw new BankrecError('E_BR_CSV_INVALID', 'CSV needs date,amount[,reference]');
    const out = [];
    for (const line of lines.slice(1)) {
        const c = line.split(',').map(x => x.trim());
        const date = c[di] ?? '';
        if (!/^\d{4}-\d{2}-\d{2}$/.test(date))
            throw new BankrecError('E_BR_CSV_INVALID', `bad date ${date}`);
        const amount = cents(c[ai] ?? '');
        const reference = c[ri] ?? '';
        const txn_id = txnId('csv', account_id, period, evidence, [side, date, amount, reference, out.length]);
        out.push({ txn_id, account_id, period, side, date, amount_cents: amount, reference, evidence_sha256: evidence, created_at: new Date().toISOString() });
    }
    return out;
}
